public int MinimumEffortPath(int[][] heights) {
    int rows = heights.Length, cols = heights[0].Length;
    var effort = new int[rows, cols];
    for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) effort[r, c] = int.MaxValue;
    effort[0, 0] = 0;
    var pq = new PriorityQueue<(int r, int c), int>();
    pq.Enqueue((0, 0), 0);
    int[] dr = { -1, 0, 1, 0 }, dc = { 0, 1, 0, -1 };
    while (pq.TryDequeue(out var cell, out int e)) {
        var (r, c) = cell;
        if (e > effort[r, c]) continue;                    // устаревшая запись
        if (r == rows - 1 && c == cols - 1) return e;      // вынули цель — окончательно
        for (int d = 0; d < 4; d++) {
            int y = r + dr[d], x = c + dc[d];
            if (y < 0 || x < 0 || y >= rows || x >= cols) continue;
            int cost = Math.Max(e, Math.Abs(heights[y][x] - heights[r][c]));  // max, а не +
            if (cost < effort[y, x]) {
                effort[y, x] = cost;
                pq.Enqueue((y, x), cost);
            }
        }
    }
    return 0;
}

