public int MinimumEffortPath(int[][] h) {
    int lo = 0, hi = 1_000_000;                    // перепад не больше 10⁶ − 1
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (CanReach(h, mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

bool CanReach(int[][] h, int limit) {            // BFS только по шагам ≤ limit
    int rows = h.Length, cols = h[0].Length;
    var seen = new bool[rows, cols];
    var queue = new Queue<(int r, int c)>();
    queue.Enqueue((0, 0));
    seen[0, 0] = true;
    int[] dr = { -1, 0, 1, 0 }, dc = { 0, 1, 0, -1 };
    while (queue.Count > 0) {
        var (r, c) = queue.Dequeue();
        if (r == rows - 1 && c == cols - 1) return true;
        for (int d = 0; d < 4; d++) {
            int y = r + dr[d], x = c + dc[d];
            if (y < 0 || x < 0 || y >= rows || x >= cols || seen[y, x]) continue;
            if (Math.Abs(h[y][x] - h[r][c]) > limit) continue;
            seen[y, x] = true;
            queue.Enqueue((y, x));
        }
    }
    return false;
}

