public int SwimInWater(int[][] grid) {
    int n = grid.Length, total = n * n;
    var cellAt = new int[total];                    // высоты 0..n²−1 все разные: время t → клетка
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) cellAt[grid[r][c]] = r * n + c;
    var parent = new int[total];
    var rank = new byte[total];
    var wet = new bool[total];
    for (int i = 0; i < total; i++) parent[i] = i;

    int Find(int x) => parent[x] == x ? x : parent[x] = Find(parent[x]);  // сжатие пути
    void Union(int a, int b) {
        a = Find(a); b = Find(b);
        if (a == b) return;
        if (rank[a] < rank[b]) (a, b) = (b, a);    // низкое дерево — под высокое
        parent[b] = a;
        if (rank[a] == rank[b]) rank[a]++;
    }

    int[] dr = { -1, 0, 1, 0 }, dc = { 0, 1, 0, -1 };
    for (int t = 0; t < total; t++) {
        int cell = cellAt[t], r = cell / n, c = cell % n;
        wet[cell] = true;                           // вода дошла до высоты t: намокла ровно эта клетка
        for (int d = 0; d < 4; d++) {
            int y = r + dr[d], x = c + dc[d];
            if (y >= 0 && x >= 0 && y < n && x < n && wet[y * n + x]) Union(cell, y * n + x);
        }
        if (wet[0] && wet[total - 1] && Find(0) == Find(total - 1)) return t;
    }
    return total - 1;
}
